package com.farika.soundflow;
import android.app.*;import android.content.*;import android.media.AudioManager;import android.net.Uri;import android.os.Bundle;import java.io.*;import java.util.*;
/** Local WAV only. Focus events are synthetic, not a real cellular call. */
final class ResumeCases {
 final Instrumentation test;final Context c;int n;final Bundle out=new Bundle();
 ResumeCases(Instrumentation t){test=t;c=t.getTargetContext();}
 void check(boolean ok,String label){if(!ok)throw new AssertionError(label);n++;out.putString(label,"PASS");}
 void main(Runnable r){test.runOnMainSync(r);}
 boolean actual(){final boolean[] r={false};main(()->{try{PlaybackService s=PlaybackService.instance;if(s==null)return;java.lang.reflect.Field f=PlaybackService.class.getDeclaredField("player");f.setAccessible(true);androidx.media3.exoplayer.ExoPlayer p=(androidx.media3.exoplayer.ExoPlayer)f.get(s);r[0]=p!=null&&p.isPlaying();}catch(Exception e){throw new RuntimeException(e);}});return r[0];}
 void waitPlaying(boolean expected)throws Exception{for(int k=0;k<100;k++){if(actual()==expected)return;Thread.sleep(100);}throw new AssertionError("actual playback expected "+expected);}
 void waitReady()throws Exception{for(int k=0;k<100;k++){final boolean[] r={false};main(()->{PlaybackService s=PlaybackService.instance;r[0]=s!=null&&!s.isLoading()&&s.duration()>0;});if(r[0])return;Thread.sleep(100);}throw new AssertionError("prepare timeout");}
 void stop()throws Exception{main(()->{if(PlaybackService.instance!=null)PlaybackService.instance.stopForLocalChange();});for(int k=0;k<50&&PlaybackService.instance!=null;k++)Thread.sleep(100);}
 Activity launch(){return test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 void fixture()throws Exception{File f=new File(c.getFilesDir(),"resume_test.wav");try(InputStream in=test.getContext().getAssets().open("test.wav");OutputStream o=new FileOutputStream(f)){byte[] b=new byte[8192];int k;while((k=in.read(b))!=-1)o.write(b,0,k);}Library l=new Library(c);for(int j=0;j<3;j++){String uri=Uri.fromFile(f).toString()+"#"+j;l.upsert(new Library.Track(uri,"Восстановление · "+(j+1),"Локальный тест",30000,false));}l.save();}
 ArrayList<String> queue(){ArrayList<String> q=new ArrayList<>();String base=Uri.fromFile(new File(c.getFilesDir(),"resume_test.wav")).toString();q.add(base+"#0");q.add(base+"#1");q.add(base+"#1");q.add(base+"#2");return q;}
 void play()throws Exception{c.startForegroundService(new Intent(c,PlaybackService.class).setAction("PLAY").putExtra("uri",queue().get(1)).putStringArrayListExtra("queue",queue()));waitReady();waitPlaying(true);}
 void run(String mode){try{
  if(mode.equals("recovery-check")){
   PlaybackCheckpoint.Snapshot s=PlaybackCheckpoint.read(c);check(s!=null&&s.queue.size()==4&&s.index==1,"process_death_queue_index_duplicates");check(s.position>=11000&&s.position<=18000,"process_death_position_durable");check(s.shuffle&&s.repeat,"process_death_modes_durable");
   Activity a=launch();Thread.sleep(700);check(PlaybackService.instance==null,"normal_open_does_not_autoplay_or_start_service");final boolean[] mini={false};main(()->{try{java.lang.reflect.Field f=MainActivity.class.getDeclaredField("miniTitle");f.setAccessible(true);mini[0]=((android.widget.TextView)f.get(a)).getText().toString().contains("Восстановление · 2");}catch(Exception e){throw new RuntimeException(e);}});check(mini[0],"saved_track_visible_after_process_death");
   c.startForegroundService(new Intent(c,PlaybackService.class).setAction("RESTORE_PAUSED"));waitReady();check(!actual(),"restore_prepares_paused");final long[] pos={0};main(()->pos[0]=PlaybackService.instance.position());check(Math.abs(pos[0]-s.position)<600,"restore_seek_preserved");main(()->PlaybackService.instance.resume());waitPlaying(true);check(actual(),"explicit_resume_after_process_death");stop();out.putInt("checks",n);test.finish(Activity.RESULT_OK,out);return;
  }
  launch();fixture();play();check(actual(),"native_playback_before_interruption");
  if(mode.equals("recovery-seed")){main(()->{PlaybackService s=PlaybackService.instance;s.seek(12000);s.shuffle=true;s.repeat=true;s.checkpoint();});Thread.sleep(800);out.putString("phase","checkpoint seeded for external process kill");test.finish(Activity.RESULT_OK,out);return;}
  main(()->PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_LOSS_TRANSIENT));waitPlaying(false);main(()->PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_LOSS_TRANSIENT));check(!actual(),"duplicate_transient_loss_stays_paused");
  final boolean[] fg={false};main(()->{try{for(android.app.ActivityManager.RunningServiceInfo r:((android.app.ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE)).getRunningServices(100))if(r.service.getClassName().equals(PlaybackService.class.getName()))fg[0]=r.foreground;}catch(Exception ignored){}});check(fg[0],"transient_pause_keeps_foreground_service");
  main(()->PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_GAIN));waitPlaying(true);check(actual(),"gain_resumes_after_duplicate_loss");
  main(()->{PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_LOSS_TRANSIENT);PlaybackService.instance.pause();PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_GAIN);});Thread.sleep(400);check(!actual(),"manual_pause_cancels_resume");
  main(()->PlaybackService.instance.resume());waitPlaying(true);main(()->PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_LOSS));main(()->PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_GAIN));check(!actual(),"permanent_loss_does_not_resume");
  main(()->{PlaybackService s=PlaybackService.instance;s.seek(9000);s.shuffle=true;s.repeat=true;s.checkpoint();});PlaybackCheckpoint.Snapshot before=PlaybackCheckpoint.read(c);check(before!=null&&before.index==1&&before.queue.size()==4,"checkpoint_full_queue_preserves_duplicates");check(before.position>=8900&&before.position<9800,"checkpoint_seek_position");check(before.shuffle&&before.repeat,"checkpoint_modes");
  stop();check(PlaybackService.instance==null,"intentional_stop_releases_service");check(PlaybackCheckpoint.read(c)!=null,"intentional_stop_keeps_resumable_checkpoint");c.startForegroundService(new Intent(c,PlaybackService.class).setAction("RESTORE_PAUSED"));waitReady();check(!actual(),"stop_then_restore_no_autoplay");final long[] pos={0};main(()->pos[0]=PlaybackService.instance.position());check(Math.abs(pos[0]-before.position)<600,"restored_native_position");
  main(()->PlaybackService.instance.resume());waitPlaying(true);main(()->PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_LOSS_TRANSIENT));main(()->{PlaybackService.instance.next();PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_LOSS_TRANSIENT);});waitReady();check(!actual(),"prepare_during_call_cannot_autoplay");main(()->PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_GAIN));waitPlaying(true);check(actual(),"gain_resumes_track_prepared_during_call");
  main(()->PlaybackService.instance.resume());waitPlaying(true);main(()->{try{java.lang.reflect.Field f=PlaybackService.class.getDeclaredField("noisy");f.setAccessible(true);((BroadcastReceiver)f.get(PlaybackService.instance)).onReceive(c,new Intent(AudioManager.ACTION_AUDIO_BECOMING_NOISY));}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(500);main(()->PlaybackService.instance.focusChanged(AudioManager.AUDIOFOCUS_GAIN));check(!actual(),"headphone_disconnect_cancels_resume");
  String old=PlaybackCheckpoint.owner(c);c.getSharedPreferences("profile",0).edit().putString("id","DIFFERENT_TEST_OWNER").commit();check(PlaybackCheckpoint.read(c)==null,"checkpoint_account_isolation");c.getSharedPreferences("profile",0).edit().putString("id",old).commit();
  stop();out.putInt("checks",n);out.putString("scope","Local WAV, synthetic focus events and service restart; no real telephone or OEM testing");test.finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("failure",e.getClass().getSimpleName()+": "+e.getMessage());test.finish(Activity.RESULT_CANCELED,out);}}
}
